    #[test]
    fn new_final_revision_rejects_stale_evidence_then_accepts_typed_current_evidence() {
        let old_revision = digest('a');
        let current_revision = digest('b');
        let spec = SpecVersionDraft {
            parent_version_id: None,
            objective: "verify the managed result".into(),
            project_ref: "project://test".into(),
            workspace_ref: "workspace://test".into(),
            capability_scope: vec![],
            scope: vec!["src/**".into()],
            constraints: Vec::new(),
            criteria: vec![AcceptanceCriterion {
                id: "tests-pass".into(),
                description: "the accepted test profile passes".into(),
            }],
            budget: SpecBudget {
                max_tasks: 1,
                max_attempts_per_task: 1,
                max_run_duration_ms: 1_000,
                max_memory_bytes: None,
                max_disk_bytes: None,
                max_workers: 1,
                max_tokens: None,
                max_cost_micros: None,
            },
            source_digests: vec![old_revision.clone()],
            proposed_by: "server_auth.author".into(),
        };
        let spec_digest = spec.digest();
        let spec_id = "spec-v1".to_owned();
        let verifier_id = "server_auth.independent".to_owned();
        let mut previous_evidence = valid_evidence();
        previous_evidence.verifier_id = verifier_id.clone();
        previous_evidence.evidence_digest = verification_evidence_digest(&previous_evidence);
        let mut snapshot = ManagedSnapshot::default();
        snapshot.specs.insert(
            spec_id.clone(),
            SpecVersion {
                digest: spec_digest,
                content: spec.clone(),
                accepted: true,
                accepted_by: Some("server_auth.reviewer".into()),
                accepted_at_ms: Some(1),
                reviewer_id: Some("server_auth.reviewer".into()),
                reviewer_assigned_revision: Some(1),
                reviewed_revision: Some(2),
                rejected_by: None,
                rejected_at_ms: None,
            },
        );
        snapshot.runs.insert(
            "run-v1".into(),
            Run {
                spec_id,
                phase: RunPhase::Verifying,
                started_at_ms: None,
                tasks: BTreeMap::from([(
                    "task-v1".into(),
                    Task {
                        dependencies: Vec::new(),
                        criterion_ids: vec!["tests-pass".into()],
                        required_capabilities: vec![],
                        agent_profile_revision: None,
                        profile_token_budget: None,
                        profile_owner_binding_digest: None,
                        ready: true,
                        active_attempt: None,
                        pending_verification_attempt: None,
                        unknown_effect: false,
                        verified_revision: Some(old_revision.clone()),
                        // A completed Task carries its independent typed proof;
                        // `verified_revision` alone is a legacy replay-only shape
                        // and no longer admits a new verification revision.
                        verification_evidence: Some(TaskVerificationEvidence {
                            attempt_id: "attempt-v1".into(),
                            verifier_id: verifier_id.clone(),
                            source_revision: old_revision.clone(),
                            evidence_digest: digest('f'),
                        }),
                        failed_criterion_ids: Vec::new(),
                        attempt_count: 1,
                        candidate_generation: 0,
                        title: None,
                        purpose: None,
                    },
                )]),
                session_link: None,
                final_revision: Some(old_revision.clone()),
                verifier_id: Some(verifier_id.clone()),
                criterion_evidence: BTreeMap::from([(
                    "tests-pass".into(),
                    CriterionEvidence {
                        source_revision: old_revision.clone(),
                        evidence_digest: digest('e'),
                        verifier_id: verifier_id.clone(),
                    },
                )]),
                verification_evidence: Some(previous_evidence.clone()),
                verification_history: Vec::new(),
                failure_code: None,
            },
        );
        snapshot
            .apply(&ManagedCommand::BeginVerification {
                run_id: "run-v1".into(),
                final_revision: current_revision.clone(),
                verifier_id: verifier_id.clone(),
            })
            .unwrap();
        assert!(snapshot.runs["run-v1"].criterion_evidence.is_empty());
        assert!(snapshot.runs["run-v1"].verification_evidence.is_none());
        assert_eq!(snapshot.runs["run-v1"].verification_history.len(), 1);
        assert!(matches!(
            snapshot.apply(&ManagedCommand::RecordVerificationEvidence {
                run_id: "run-v1".into(),
                evidence: previous_evidence,
            }),
            Err(ManagedError::Conflict(_))
        ));

        let mut current_evidence = valid_evidence();
        current_evidence.verification_run_id = "verify-run-current".into();
        current_evidence.verifier_id = verifier_id;
        current_evidence.source_revision = current_revision.clone();
        current_evidence.evidence_digest = verification_evidence_digest(&current_evidence);
        // The settled Attempt must carry the exact trusted verifier evidence the
        // Run records; finalization re-derives the per-Task typed digest from it.
        snapshot.attempts.insert("attempt-v1".into(), AttemptRecord {
            run_id: "run-v1".into(),
            task_id: "task-v1".into(),
            executor_principal: "server_auth.executor".into(),
            owner_epoch: current_evidence.profile.owner_epoch,
            location_id: "location-1".into(),
            session_id: "session-1".into(),
            workspace_revision: Some(old_revision.clone()),
            delegation_binding: None,
            effects: vec![BoundEffect {
                effect_id: "effect-v1".into(),
                location_id: "location-1".into(),
                session_id: "session-1".into(),
                bound_revision: 1,
            }],
            effect_waves: Vec::new(),
            effect_receipts: BTreeMap::from([(
                "effect-v1".to_owned(),
                ManagedAttemptEffectReceiptV1 {
                    executor_principal: "server_auth.executor".into(),
                    owner_epoch: current_evidence.profile.owner_epoch,
                    bound_revision: 1,
                    location_id: "location-1".into(),
                    session_id: "session-1".into(),
                    capability_id: "files.write".into(),
                    capability_lease_digest: digest('b'),
                    outcome: AttemptEffectOutcomeV1::Succeeded,
                    target_receipt_digest: Some(digest('e')),
                    before_workspace_revision: old_revision.clone(),
                    after_workspace_revision: Some(old_revision.clone()),
                },
            )]),
            verifier_intents: BTreeMap::new(),
            verifier_evidence: Some(current_evidence.clone()),
            phase: AttemptPhase::Succeeded,
            receipt_digest: Some(digest('c')),
            failure_code: None,
            retryable: None,
        });

        snapshot
            .apply(&ManagedCommand::RecordVerificationEvidence {
                run_id: "run-v1".into(),
                evidence: current_evidence,
            })
            .unwrap();
        snapshot
            .apply(&ManagedCommand::FinalizeRun {
                run_id: "run-v1".into(),
                final_revision: current_revision,
            })
            .unwrap();
        assert_eq!(snapshot.runs["run-v1"].phase, RunPhase::Succeeded);
        assert_eq!(snapshot.runs["run-v1"].verification_history.len(), 1);
    }

    #[test]
    fn finalize_run_rejects_multiple_task_proofs_before_final_revision() {
        let old_revision = digest('a');
        let final_revision = digest('b');
        let verifier_id = "server_auth.independent".to_owned();
        let spec = SpecVersionDraft {
            parent_version_id: None,
            objective: "verify all managed Tasks at the final workspace revision".into(),
            project_ref: "project://test".into(),
            workspace_ref: "workspace://test".into(),
            capability_scope: vec![],
            scope: vec!["src/**".into()],
            constraints: Vec::new(),
            criteria: vec![
                AcceptanceCriterion { id: "tests-pass".into(), description: "tests pass".into() },
                AcceptanceCriterion { id: "lint-pass".into(), description: "lint passes".into() },
            ],
            budget: SpecBudget {
                max_tasks: 2,
                max_attempts_per_task: 1,
                max_run_duration_ms: 1_000,
                max_memory_bytes: None,
                max_disk_bytes: None,
                max_workers: 2,
                max_tokens: None,
                max_cost_micros: None,
            },
            source_digests: vec![old_revision.clone()],
            proposed_by: "server_auth.author".into(),
        };
        let spec_digest = spec.digest();
        let mut snapshot = ManagedSnapshot::default();
        snapshot.specs.insert(
            "spec-multi-final".into(),
            SpecVersion {
                digest: spec_digest,
                content: spec,
                accepted: true,
                accepted_by: Some("server_auth.reviewer".into()),
                accepted_at_ms: Some(1),
                reviewer_id: Some("server_auth.reviewer".into()),
                reviewer_assigned_revision: Some(1),
                reviewed_revision: Some(2),
                rejected_by: None,
                rejected_at_ms: None,
            },
        );

        let make_task_attempt = |task_id: &str, criterion_id: &str, attempt_id: &str,
                                 effect_id: &str, receipt_seed: char| {
            let mut evidence = valid_evidence();
            evidence.verifier_id = verifier_id.clone();
            evidence.source_revision = old_revision.clone();
            evidence.criteria[0].criterion_id = criterion_id.into();
            evidence.evidence_digest = verification_evidence_digest(&evidence);
            let receipt_digest = digest(receipt_seed);
            let criterion_ids = vec![criterion_id.to_owned()];
            let task_evidence = TaskVerificationEvidence {
                attempt_id: attempt_id.into(),
                verifier_id: verifier_id.clone(),
                source_revision: old_revision.clone(),
                evidence_digest: task_typed_verification_digest(
                    task_id, attempt_id, &receipt_digest, &criterion_ids, &evidence,
                ),
            };
            let task = Task {
                candidate_generation: 0,
                title: None,
                purpose: None,
                dependencies: Vec::new(),
                criterion_ids,
                required_capabilities: Vec::new(),
                agent_profile_revision: None,
                profile_token_budget: None,
                profile_owner_binding_digest: None,
                ready: false,
                active_attempt: None,
                pending_verification_attempt: None,
                unknown_effect: false,
                verified_revision: Some(old_revision.clone()),
                verification_evidence: Some(task_evidence),
                failed_criterion_ids: Vec::new(),
                attempt_count: 1,
            };
            let attempt = AttemptRecord {
                run_id: "run-multi-final".into(),
                task_id: task_id.into(),
                executor_principal: "server_auth.executor".into(),
                owner_epoch: evidence.profile.owner_epoch,
                location_id: "location-1".into(),
                session_id: format!("session-{task_id}"),
                workspace_revision: Some(old_revision.clone()),
                delegation_binding: None,
                effects: vec![BoundEffect {
                    effect_id: effect_id.into(),
                    location_id: "location-1".into(),
                    session_id: format!("session-{task_id}"),
                    bound_revision: 1,
                }],
                effect_waves: Vec::new(),
                effect_receipts: BTreeMap::from([(
                    effect_id.into(),
                    ManagedAttemptEffectReceiptV1 {
                        executor_principal: "server_auth.executor".into(),
                        owner_epoch: evidence.profile.owner_epoch,
                        bound_revision: 1,
                        location_id: "location-1".into(),
                        session_id: format!("session-{task_id}"),
                        capability_id: "files.write".into(),
                        capability_lease_digest: digest('c'),
                        outcome: AttemptEffectOutcomeV1::Succeeded,
                        target_receipt_digest: Some(digest('d')),
                        before_workspace_revision: old_revision.clone(),
                        after_workspace_revision: Some(old_revision.clone()),
                    },
                )]),
                verifier_intents: BTreeMap::new(),
                verifier_evidence: Some(evidence),
                phase: AttemptPhase::Succeeded,
                receipt_digest: Some(receipt_digest),
                failure_code: None,
                retryable: None,
            };
            (task, attempt)
        };

        let (task_one, attempt_one) = make_task_attempt("task-one", "tests-pass", "attempt-one", "effect-one", 'e');
        let (task_two, attempt_two) = make_task_attempt("task-two", "lint-pass", "attempt-two", "effect-two", 'f');
        snapshot.attempts.insert("attempt-one".into(), attempt_one);
        snapshot.attempts.insert("attempt-two".into(), attempt_two);
        snapshot.runs.insert(
            "run-multi-final".into(),
            Run {
                spec_id: "spec-multi-final".into(),
                phase: RunPhase::Verifying,
                started_at_ms: None,
                tasks: BTreeMap::from([
                    ("task-one".into(), task_one),
                    ("task-two".into(), task_two),
                ]),
                session_link: None,
                final_revision: Some(old_revision.clone()),
                verifier_id: Some(verifier_id.clone()),
                criterion_evidence: BTreeMap::new(),
                verification_evidence: None,
                verification_history: Vec::new(),
                failure_code: None,
            },
        );
        snapshot.apply(&ManagedCommand::BeginVerification {
            run_id: "run-multi-final".into(),
            final_revision: final_revision.clone(),
            verifier_id,
        }).unwrap();

        let result = snapshot.apply(&ManagedCommand::FinalizeRun {
            run_id: "run-multi-final".into(),
            final_revision,
        });

        assert!(matches!(
            result,
            Err(ManagedError::Conflict(
                "Task aggregate evidence or settled receipt is stale or incomplete"
            ))
        ));
        assert_eq!(snapshot.runs["run-multi-final"].phase, RunPhase::Verifying);
    }

    #[test]
